package com.inventra.backend.controller; import com.inventra.backend.dto.PurchaseOrderRequest; import com.inventra.backend.model.PurchaseOrder; import com.inventra.backend.service.PurchaseOrderService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/purchase-orders") public class PurchaseOrderController {private final PurchaseOrderService s;public PurchaseOrderController(PurchaseOrderService s){this.s=s;}@PostMapping public PurchaseOrder create(@Valid @RequestBody PurchaseOrderRequest r){return s.create(r);}@GetMapping public List<PurchaseOrder> all(){return s.all();}@PostMapping("/{id}/receive") public PurchaseOrder receive(@PathVariable String id){return s.receive(id);}}
